    "html": "<div class=\"mx-table-container\" tabindex=\"0\" role=\"region\" aria-label=\"Contacts, with horizontal scroll\">\n  <table mxTable density=\"compact\">\n    <thead><tr><th scope=\"col\">Name</th><th scope=\"col\">Company</th><th scope=\"col\">Email</th><th scope=\"col\">Phone</th><th scope=\"col\">Province</th></tr></thead>\n    <tbody>\n      <tr><td>Ana Kiala</td><td>Kianda Logistics</td><td>ana@kianda.co.ao</td><td>+244 923 000 111</td><td>Luanda</td></tr>\n      <tr><td>Pedro Neto</td><td>Huíla Agro</td><td>pedro@huila-agro.ao</td><td>+244 924 000 222</td><td>Huíla</td></tr>\n    </tbody>\n  </table>\n</div>",
