    "html": "<label mxChoice><input type=\"checkbox\" mxCheckbox size=\"sm\" checked /> Small</label>\n<label mxChoice><input type=\"checkbox\" mxCheckbox checked /> Medium</label>\n<label mxChoice><input type=\"checkbox\" mxCheckbox size=\"lg\" checked /> Large</label>",
