  "components/card|Clickable card": {
    "html": "<a mxCard routerLink=\"/components/table\">\n  <div mxCardHeader>\n    <h3 mxCardTitle>Table</h3>\n    <p mxCardDescription>Tabular data with accessible sorting.</p>\n  </div>\n</a>",
    "ts": "import { Component } from '@angular/core';\nimport { RouterLink } from '@angular/router';\nimport { MX_CARD } from '@muxima-ui/core/card';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MX_CARD, RouterLink],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
  "components/card|States": {
    "html": "<!-- Default -->\n<a mxCard href=\"#\"><span mxCardContent>Customers</span></a>\n\n<!-- Hover: Darker border. -->\n<a mxCard href=\"#\" data-mx-state=\"hover\"><span mxCardContent>Customers</span></a>\n\n<!-- Focus -->\n<a mxCard href=\"#\" data-mx-state=\"focus\"><span mxCardContent>Customers</span></a>\n\n<!-- Loading: Skeleton in place of the content. -->\n<div mxCard aria-busy=\"true\"><div mxCardContent><div mxSkeleton shape=\"text\"></div><div mxSkeleton shape=\"text\"></div></div></div>\n\n<!-- Empty -->\n<div mxCard><p mxCardContent>No data</p></div>",
    "ts": "import { Component } from '@angular/core';\nimport { MX_CARD } from '@muxima-ui/core/card';\nimport { MxSkeleton } from '@muxima-ui/core/skeleton';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MX_CARD, MxSkeleton],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
  "components/alert|After an action": {
    "html": "<div>\n  <div><button mxButton type=\"button\" variant=\"outline\" (click)=\"send()\">Send invoices</button></div>\n  @if (result() === 'error') {\n    <div mxAlert variant=\"danger\" announce>\n      <p mxAlertTitle>Couldn't send</p>\n      <p>Check your connection and try again.</p>\n    </div>\n  }\n</div>",
    "ts": "import { Component, signal } from '@angular/core';\nimport { MX_ALERT } from '@muxima-ui/core/alert';\nimport { MxButton } from '@muxima-ui/core/button';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MX_ALERT, MxButton],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {\n  protected readonly result = signal<'error' | null>(null);\n\n  protected send(): void {\n    this.result.set(null);\n    setTimeout(() => this.result.set('error'), 300);\n  }\n}"
  },
  "components/alert|With an action": {
    "html": "<div mxAlert>\n  <p mxAlertTitle>Turn on two-step verification</p>\n  <p>Protects your account even if your password is discovered.</p>\n  <div><button mxButton type=\"button\" size=\"sm\" variant=\"outline\">Turn on</button></div>\n</div>",
    "ts": "import { Component } from '@angular/core';\nimport { MX_ALERT } from '@muxima-ui/core/alert';\nimport { MxButton } from '@muxima-ui/core/button';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MX_ALERT, MxButton],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
  "components/alert|Variants": {
    "html": "<div>\n  <div mxAlert><p mxAlertTitle>Information</p><p>The tax authority updated the invoicing rules.</p></div>\n  <div mxAlert variant=\"success\"><p mxAlertTitle>All up to date</p><p>Every October invoice has been paid.</p></div>\n  <div mxAlert variant=\"warning\"><p mxAlertTitle>Warning</p><p>The digital certificate expires in 12 days.</p></div>\n  <div mxAlert variant=\"danger\"><p mxAlertTitle>Error</p><p>Couldn't connect to the bank.</p></div>\n</div>",
    "ts": "import { Component } from '@angular/core';\nimport { MX_ALERT } from '@muxima-ui/core/alert';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MX_ALERT],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
  "components/alert|With a close button": {
    "html": "<div>\n  @if (showInfo()) {\n    <div mxAlert>\n      <p mxAlertTitle>New</p>\n      <p>You can now export invoices to CSV.</p>\n      <button mxAlertClose (click)=\"showInfo.set(false)\"></button>\n    </div>\n  } @else {\n    <div><button mxButton type=\"button\" variant=\"outline\" size=\"sm\" (click)=\"showInfo.set(true)\">Show again</button></div>\n  }\n</div>",
    "ts": "import { Component, signal } from '@angular/core';\nimport { MX_ALERT } from '@muxima-ui/core/alert';\nimport { MxButton } from '@muxima-ui/core/button';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MX_ALERT, MxButton],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {\n  protected readonly showInfo = signal(true);\n}"
  },
