    "ts": "import { Component } from '@angular/core';\nimport { MxCopyButton } from '@muxima-ui/core/clipboard';\nimport { MxFormField, MxInput, MxInputGroup, MxLabel } from '@muxima-ui/core/form-field';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxCopyButton, MxLabel, MxFormField, MxInputGroup, MxInput],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {\n  protected readonly link = 'https://kianda.ao/f/FT-2026-0142';\n}"
