  "pt/componentes/button|Estados": {
    "html": "<!-- Normal -->\n<button mxButton type=\"button\">Guardar</button>\n\n<!-- Hover: Fundo mais escuro. -->\n<button mxButton type=\"button\" data-mx-state=\"hover\">Guardar</button>\n\n<!-- Foco: Anel de 2 px, só com teclado. -->\n<button mxButton type=\"button\" data-mx-state=\"focus\">Guardar</button>\n\n<!-- Activo: Enquanto é premido. -->\n<button mxButton type=\"button\" data-mx-state=\"active\">Guardar</button>\n\n<!-- Desactivado: disabled -->\n<button mxButton type=\"button\" disabled>Guardar</button>\n\n<!-- A carregar: loading: aria-busy e cliques bloqueados. -->\n<button mxButton type=\"button\" loading>A guardar</button>",
    "ts": "import { Component } from '@angular/core';\nimport { MxButton } from '@muxima-ui/core/button';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxButton],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
  "pt/componentes/input|Validação": {
    "html": "<form [formGroup]=\"form\" (ngSubmit)=\"submit()\">\n  <mx-form-field>\n    <label mxLabel>Nome da empresa</label>\n    <input mxInput formControlName=\"empresa\" required />\n    <mx-error>Indica o nome da empresa.</mx-error>\n  </mx-form-field>\n  <mx-form-field>\n    <label mxLabel>NIF</label>\n    <input mxInput formControlName=\"nif\" inputmode=\"numeric\" />\n    <mx-hint>9 a 14 algarismos.</mx-hint>\n    <mx-error>O NIF tem de ter entre 9 e 14 algarismos.</mx-error>\n  </mx-form-field>\n  <div><button mxButton type=\"submit\">Validar</button></div>\n</form>",
    "ts": "import { Component } from '@angular/core';\nimport { ReactiveFormsModule, FormControl, FormGroup, Validators } from '@angular/forms';\nimport { MxButton } from '@muxima-ui/core/button';\nimport { MxError, MxFormField, MxHint, MxInput, MxLabel } from '@muxima-ui/core/form-field';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxButton, MxHint, MxError, MxLabel, MxFormField, MxInput, ReactiveFormsModule],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {\n  protected readonly form = new FormGroup({\n    empresa: new FormControl('', Validators.required),\n    nif: new FormControl('', [Validators.required, Validators.pattern(/^\\d{9,14}$/)]),\n  });\n\n  protected submit(): void {\n    this.form.markAllAsTouched();\n  }\n}"
  },
