  "pt/componentes/table|Estados": {
    "html": "<!-- Normal -->\n<div class=\"mx-table-container\"><table mxTable density=\"compact\"><thead><tr><th scope=\"col\">Cliente</th></tr></thead><tbody><tr><td>Huíla Agro</td></tr></tbody></table></div>\n\n<!-- Hover: Fundo suave na linha. -->\n<div class=\"mx-table-container\"><table mxTable density=\"compact\"><thead><tr><th scope=\"col\">Cliente</th></tr></thead><tbody><tr data-mx-state=\"hover\"><td>Huíla Agro</td></tr></tbody></table></div>\n\n<!-- Seleccionada: aria-selected=\"true\" -->\n<div class=\"mx-table-container\"><table mxTable density=\"compact\"><thead><tr><th scope=\"col\">Cliente</th></tr></thead><tbody><tr aria-selected=\"true\"><td>Huíla Agro</td></tr></tbody></table></div>\n\n<!-- Ordenada: aria-sort e ícone Kwanza. -->\n<div class=\"mx-table-container\"><table mxTable density=\"compact\"><thead><tr> <th scope=\"col\" aria-sort=\"ascending\"><span class=\"mx-sort-button\">Cliente <svg class=\"mx-sort-icon\" viewBox=\"0 0 16 16\" fill=\"none\" aria-hidden=\"true\"><path d=\"M8 12V4M5 7l3-3 3 3\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></svg></span></th></tr></thead><tbody><tr><td>Huíla Agro</td></tr></tbody></table></div>\n\n<!-- A carregar: aria-busy=\"true\" no table. -->\n<div class=\"mx-table-container\"><table mxTable density=\"compact\" aria-busy=\"true\"><thead><tr><th scope=\"col\">Cliente</th></tr></thead><tbody><tr><td>Huíla Agro</td></tr></tbody></table></div>\n\n<!-- Vazio: Célula mx-table-empty. -->\n<div class=\"mx-table-container\"><table mxTable density=\"compact\"><thead><tr><th scope=\"col\">Cliente</th></tr></thead><tbody><tr><td class=\"mx-table-empty\">Sem resultados</td></tr></tbody></table></div>",
    "ts": "import { Component } from '@angular/core';\nimport { MX_TABLE } from '@muxima-ui/core/table';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MX_TABLE],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
  "pt/componentes/textarea|Contador de caracteres": {
    "html": "<mx-form-field>\n  <label mxLabel>Descrição do projecto</label>\n  <textarea mxInput rows=\"4\" [formControl]=\"descricao\" [attr.maxlength]=\"max\"></textarea>\n  <mx-hint>{{ restantes() }} caracteres restantes</mx-hint>\n  <mx-error>Escreve pelo menos 20 caracteres.</mx-error>\n</mx-form-field>",
    "ts": "import { Component, signal, computed } from '@angular/core';\nimport { ReactiveFormsModule, FormControl, Validators } from '@angular/forms';\nimport { MxError, MxFormField, MxHint, MxInput, MxLabel } from '@muxima-ui/core/form-field';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxHint, MxError, MxLabel, MxFormField, MxInput, ReactiveFormsModule],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {\n  protected readonly max = 280;\n\n  protected readonly descricao = new FormControl('', [Validators.required, Validators.minLength(20)]);\n\n  private readonly texto = signal('');\n\n  protected readonly restantes = computed(() => this.max - this.texto().length);\n\n  constructor() {\n    this.descricao.valueChanges.subscribe((v) => this.texto.set(v ?? ''));\n  }\n}"
  },
  "pt/componentes/textarea|Altura automática": {
    "html": "<mx-form-field>\n  <label mxLabel>Mensagem</label>\n  <textarea mxInput autosize rows=\"2\" placeholder=\"Escreve várias linhas para ver o campo crescer\"></textarea>\n</mx-form-field>",
    "ts": "import { Component } from '@angular/core';\nimport { MxFormField, MxInput, MxLabel } from '@muxima-ui/core/form-field';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxLabel, MxFormField, MxInput],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
