  "pt/componentes/textarea|Comentário com acções": {
    "html": "<form (submit)=\"$event.preventDefault(); sendComment()\">\n  <mx-form-field>\n    <label mxLabel>Comentário</label>\n    <textarea mxInput autosize rows=\"2\" placeholder=\"Escreve um comentário\" [value]=\"comment()\" (input)=\"comment.set($any($event.target).value)\" (keydown.control.enter)=\"sendComment()\"></textarea>\n  </mx-form-field>\n  <div>\n    <button mxButton type=\"button\" variant=\"ghost\" size=\"sm\" (click)=\"comment.set('')\">Cancelar</button>\n    <button mxButton type=\"submit\" size=\"sm\" [disabled]=\"!comment().trim()\">Comentar</button>\n  </div>\n  @if (sent()) {\n    <p aria-live=\"polite\">Comentário enviado.</p>\n  }\n</form>",
    "ts": "import { Component, signal } from '@angular/core';\nimport { MxButton } from '@muxima-ui/core/button';\nimport { MxFormField, MxInput, MxLabel } from '@muxima-ui/core/form-field';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxButton, MxLabel, MxFormField, MxInput],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {\n  protected readonly comment = signal('');\n\n  protected readonly sent = signal(false);\n\n  protected sendComment(): void {\n    if (!this.comment().trim()) return;\n    this.comment.set('');\n    this.sent.set(true);\n  }\n}"
  },
  "pt/componentes/textarea|Estados": {
    "html": "<!-- Vazio: Mostra o placeholder. -->\n<textarea mxInput rows=\"2\" placeholder=\"Escreve aqui\" aria-label=\"Vazio\"></textarea>\n\n<!-- Normal -->\n<textarea mxInput rows=\"2\" aria-label=\"Normal\">Entregar de manhã.</textarea>\n\n<!-- Hover -->\n<textarea mxInput rows=\"2\" aria-label=\"Hover\" data-mx-state=\"hover\">Entregar de manhã.</textarea>\n\n<!-- Foco -->\n<textarea mxInput rows=\"2\" aria-label=\"Foco\" data-mx-state=\"focus\">Entregar de manhã.</textarea>\n\n<!-- Desactivado -->\n<textarea mxInput rows=\"2\" aria-label=\"Desactivado\" disabled>Entregar de manhã.</textarea>\n\n<!-- Erro -->\n<textarea mxInput rows=\"2\" aria-label=\"Erro\" invalid>Ok</textarea>",
    "ts": "import { Component } from '@angular/core';\nimport { MxInput } from '@muxima-ui/core/form-field';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxInput],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
  "pt/componentes/checkbox|Obrigatório, com Reactive Forms": {
    "html": "<div>\n  <mx-form-field>\n    <label mxChoice><input type=\"checkbox\" mxCheckbox [formControl]=\"termos\" /> Li e aceito os termos de serviço</label>\n    <mx-error>Tens de aceitar os termos para continuar.</mx-error>\n  </mx-form-field>\n  <div><button mxButton type=\"button\" (click)=\"termos.markAsTouched()\">Continuar</button></div>\n</div>",
    "ts": "import { Component } from '@angular/core';\nimport { ReactiveFormsModule, FormControl, Validators } from '@angular/forms';\nimport { MxButton } from '@muxima-ui/core/button';\nimport { MxCheckbox } from '@muxima-ui/core/checkbox';\nimport { MxChoice, MxError, MxFormField } from '@muxima-ui/core/form-field';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxButton, MxCheckbox, MxChoice, MxError, MxFormField, ReactiveFormsModule],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {\n  protected readonly termos = new FormControl(false, Validators.requiredTrue);\n}"
  },
  "pt/componentes/checkbox|Seleccionar todos": {
    "html": "<fieldset mxFieldset>\n  <legend class=\"mx-visually-hidden\">Províncias</legend>\n  <label mxChoice>\n    <input type=\"checkbox\" mxCheckbox [checked]=\"allChecked()\" [indeterminate]=\"someChecked()\" (change)=\"toggleAll()\" />\n    Todas as províncias\n  </label>\n  @for (p of provincias; track p; let i = $index) {\n    <label mxChoice>\n      <input type=\"checkbox\" mxCheckbox [checked]=\"marcadas()[i]\" (change)=\"toggle(i)\" /> {{ p }}\n    </label>\n  }\n</fieldset>",
    "ts": "import { Component, signal, computed } from '@angular/core';\nimport { MxCheckbox } from '@muxima-ui/core/checkbox';\nimport { MxChoice, MxFieldset } from '@muxima-ui/core/form-field';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxCheckbox, MxChoice, MxFieldset],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {\n  protected readonly provincias = ['Luanda', 'Benguela', 'Huíla'];\n\n  protected readonly marcadas = signal([true, false, false]);\n\n  protected readonly allChecked = computed(() => this.marcadas().every(Boolean));\n\n  protected readonly someChecked = computed(() => this.marcadas().some(Boolean) && !this.allChecked());\n\n  protected toggle(i: number): void {\n    this.marcadas.update((m) => m.map((v, j) => (j === i ? !v : v)));\n  }\n\n  protected toggleAll(): void {\n    const next = !this.allChecked();\n    this.marcadas.update((m) => m.map(() => next));\n  }\n}"
  },
  "pt/componentes/checkbox|Tamanhos": {
    "html": "<label mxChoice><input type=\"checkbox\" mxCheckbox size=\"sm\" checked /> Pequeno</label>\n<label mxChoice><input type=\"checkbox\" mxCheckbox checked /> Médio</label>\n<label mxChoice><input type=\"checkbox\" mxCheckbox size=\"lg\" checked /> Grande</label>",
    "ts": "import { Component } from '@angular/core';\nimport { MxCheckbox } from '@muxima-ui/core/checkbox';\nimport { MxChoice } from '@muxima-ui/core/form-field';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxCheckbox, MxChoice],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
