  "pt/componentes/skeleton|Indicadores": {
    "html": "<div aria-busy=\"true\">\n  @for (i of [1, 2, 3]; track i) {\n    <div class=\"mx-card\"><div class=\"mx-card-content\"><div mxSkeleton shape=\"text\"></div><div mxSkeleton></div></div></div>\n  }\n</div>",
    "ts": "import { Component } from '@angular/core';\nimport { MxSkeleton } from '@muxima-ui/core/skeleton';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxSkeleton],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
  "pt/componentes/skeleton|Estados": {
    "html": "<!-- Texto: shape=text, 0,8 em de altura. -->\n<div mxSkeleton shape=\"text\"></div>\n\n<!-- Círculo: shape=circle -->\n<div mxSkeleton shape=\"circle\"></div>\n\n<!-- Bloco: shape=block -->\n<div mxSkeleton></div>",
    "ts": "import { Component } from '@angular/core';\nimport { MxSkeleton } from '@muxima-ui/core/skeleton';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxSkeleton],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
  "pt/componentes/progress|Envio com progresso": {
    "html": "<div>\n  <div><button mxButton type=\"button\" variant=\"outline\" size=\"sm\" (click)=\"start()\" [disabled]=\"value() > 0 && value() < 100\">Enviar 30 facturas</button></div>\n  <label for=\"ex-envio\">{{ value() >= 100 ? 'Concluído' : 'Enviadas ' + sent() + ' de 30' }}</label>\n  <progress id=\"ex-envio\" mxProgress [value]=\"value()\" max=\"100\"></progress>\n</div>",
    "ts": "import { Component, signal } from '@angular/core';\nimport { MxButton } from '@muxima-ui/core/button';\nimport { MxProgress } from '@muxima-ui/core/progress';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxButton, MxProgress],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {\n  protected readonly value = signal(0);\n\n  protected readonly sent = signal(0);\n\n  protected start(): void {\n    this.value.set(0);\n    this.sent.set(0);\n    const tick = setInterval(() => {\n      this.sent.update((n) => n + 3);\n      this.value.set(Math.round((this.sent() / 30) * 100));\n      if (this.sent() >= 30) clearInterval(tick);\n    }, 250);\n  }\n}"
  },
  "pt/componentes/progress|Tamanhos": {
    "html": "<div>\n  <progress mxProgress size=\"sm\" value=\"30\" max=\"100\" aria-label=\"Pequeno\"></progress>\n  <progress mxProgress value=\"50\" max=\"100\" aria-label=\"Médio\"></progress>\n  <progress mxProgress size=\"lg\" value=\"70\" max=\"100\" aria-label=\"Grande\"></progress>\n</div>",
    "ts": "import { Component } from '@angular/core';\nimport { MxProgress } from '@muxima-ui/core/progress';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxProgress],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
  "pt/componentes/progress|Vários ficheiros": {
    "html": "<ul>\n  @for (f of ficheiros; track f.nome) {\n    <li>\n      <div><label [for]=\"'up-' + $index\">{{ f.nome }}</label><span>{{ f.valor === 100 ? 'Concluído' : f.valor + '%' }}</span></div>\n      <progress [id]=\"'up-' + $index\" mxProgress size=\"sm\" [value]=\"f.valor\" max=\"100\"></progress>\n    </li>\n  }\n</ul>",
    "ts": "import { Component } from '@angular/core';\nimport { MxProgress } from '@muxima-ui/core/progress';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxProgress],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {\n  protected readonly ficheiros = [\n    { nome: 'facturas-outubro.pdf', valor: 100 },\n    { nome: 'extracto-banco.xlsx', valor: 64 },\n    { nome: 'contratos.zip', valor: 12 },\n  ];\n}"
  },
